"""Структура, которую обязана вернуть цепочка извлечения.

Описания полей — это спецификация для модели: LangChain передаёт их вместе со схемой. Написаны для
аналитика, читающего ленту: он смотрит `summary`, затем сортирует по `category` и `priority`.
"""

from pydantic import BaseModel, Field

from sumnews.typed import CategoryValue, PriorityValue


class Extraction(BaseModel):
    is_relevant: bool = Field(description="True, если статья несёт содержательную информацию для аналитика, следящего за отслеживаемой компанией: событие с участием компании или названного конкурента (regulation / reputation / competitors), значимый отраслевой, регуляторный или рыночный сдвиг, затрагивающий их сектор (trends), либо собственное промо отслеживаемой компании (promo). False только для беглого упоминания в проброс, одного пункта в подборке-списке или материала, не связанного ни с компанией, ни с её сектором и совпавшего лишь по ключевому слову.")
    relevance_reason: str = Field(description="Одно предложение: какого отслеживаемого субъекта касается статья и что произошло, либо почему материал нерелевантен.")
    summary: str = Field(description="2–4 предложения, фактологично и самодостаточно. Назови действующих лиц, конкретное событие и все упомянутые цифры, даты и регуляторов. Не пиши «в статье говорится» и не смягчай формулировки — излагай, что произошло.")
    category: CategoryValue = Field(description="regulation: законы, регуляторы, лицензирование, штрафы, судебные разбирательства, комплаенс. reputation: общественное восприятие, PR-кризисы, скандалы, настроения клиентов или сотрудников, сбои в работе. competitors: продукты, сделки, финансирование, найм или рыночные шаги конкурента. trends: отраслевые сдвиги, технологии или рыночные данные, не привязанные к одной компании. promo: реклама, промо-акции или собственные заявления/пресс-релизы самой отслеживаемой компании, а не внешнее освещение о ней.")
    priority: PriorityValue = Field(description="high: действия регулятора, судебный иск или кризис, прямо называющий отслеживаемую компанию. medium: шаги конкурентов или регуляторные/отраслевые сдвиги с явным краткосрочным влиянием на отслеживаемую компанию. low: общие тренды и косвенные упоминания.")
    priority_reason: str = Field(description="Одно предложение с обоснованием выбранного уровня приоритета.")
